class Solution {
  public int numOfArrays(int n, int m, int k) {
    final int MOD = 1_000_000_007;
    long[][] dp = new long[m + 1][k + 1];
    for (int maximum = 1; maximum <= m; maximum++) dp[maximum][1] = 1;
    for (int length = 2; length <= n; length++) {
      long[][] next = new long[m + 1][k + 1];
      long[][] prefix = new long[m + 1][k + 1];
      for (int maximum = 1; maximum <= m; maximum++) {
        for (int cost = 1; cost <= k; cost++) {
          prefix[maximum][cost] = (prefix[maximum - 1][cost] + dp[maximum][cost]) % MOD;
          next[maximum][cost] = dp[maximum][cost] * maximum % MOD;
          if (cost > 1)
            next[maximum][cost] = (next[maximum][cost] + prefix[maximum - 1][cost - 1]) % MOD;
        }
      }
      dp = next;
    }
    long result = 0;
    for (int maximum = 1; maximum <= m; maximum++) result = (result + dp[maximum][k]) % MOD;
    return (int) result;
  }
}
